try {
  const items = $input.all();
  const apis = items.map(item => item.json).filter(r => r && r.ApiCode);

  if (!apis.length) {
    return [{ json: { api_list_text: '(Không lấy được danh sách API từ hệ thống)' } }];
  }

  const grouped = {};
  for (const api of apis) {
    const cat = api.Category || 'Khác';
    if (!grouped[cat]) grouped[cat] = [];
    grouped[cat].push(`• ${api.ApiCode}  → ${api.ApiDescription || api.ApiName}  [${api.ExecutionType}]`);
  }

  let text = 'DANH SÁCH API HỆ THỐNG (tự động từ DB):\n';
  for (const [cat, groupItems] of Object.entries(grouped)) {
    text += `\n===== ${cat} =====\n${groupItems.join('\n')}`;
  }

  return [{ json: { api_list_text: text } }];
} catch (e) {
  return [{ json: { api_list_text: '(Lỗi khi xử lý danh sách API: ' + e.message + ')' } }];
}

